DECLARE
  CURSOR c IS SELECT acct_id, interest FROM interest_due;
  TYPE t_tab IS TABLE OF c%ROWTYPE;
  l_rows t_tab;
  bulk_errors EXCEPTION;
  PRAGMA EXCEPTION_INIT(bulk_errors, -24381);
BEGIN
  OPEN c;
  LOOP
    FETCH c BULK COLLECT INTO l_rows LIMIT 10000;
    EXIT WHEN l_rows.COUNT = 0;
    BEGIN
      FORALL i IN 1 .. l_rows.COUNT SAVE EXCEPTIONS
        UPDATE acct_balance
           SET balance = balance + l_rows(i).interest
         WHERE acct_id = l_rows(i).acct_id;
    EXCEPTION
      WHEN bulk_errors THEN
        FOR j IN 1 .. SQL%BULK_EXCEPTIONS.COUNT LOOP
          INSERT INTO err_log (acct_id, err_code, logged_on)
          VALUES (l_rows(SQL%BULK_EXCEPTIONS(j).ERROR_INDEX).acct_id,
                  SQL%BULK_EXCEPTIONS(j).ERROR_CODE, SYSDATE);
        END LOOP;
    END;
    COMMIT;
  END LOOP;
  CLOSE c;
END;
/

CREATE OR REPLACE PROCEDURE transfer (
  p_from IN NUMBER, p_to IN NUMBER, p_amt IN NUMBER
) IS
  l_bal acct_balance.balance%TYPE;
  CURSOR c_lock IS
    SELECT acct_id, balance FROM acct_balance
    WHERE acct_id IN (p_from, p_to)
    ORDER BY acct_id
    FOR UPDATE;
BEGIN
  IF p_amt <= 0 OR p_from = p_to THEN
    RAISE_APPLICATION_ERROR(-20001, 'Invalid transfer request');
  END IF;

  FOR r IN c_lock LOOP           -- locks both rows in acct_id order
    IF r.acct_id = p_from THEN l_bal := r.balance; END IF;
  END LOOP;

  IF l_bal IS NULL THEN
    RAISE_APPLICATION_ERROR(-20002, 'Source account not found');
  ELSIF l_bal < p_amt THEN
    RAISE_APPLICATION_ERROR(-20003, 'Insufficient funds');
  END IF;

  UPDATE acct_balance SET balance = balance - p_amt WHERE acct_id = p_from;
  UPDATE acct_balance SET balance = balance + p_amt WHERE acct_id = p_to;
  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20004, 'Target account not found');
  END IF;
END transfer;
/

CREATE OR REPLACE PROCEDURE log_event (
  p_event   IN VARCHAR2,
  p_details IN VARCHAR2
) IS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO audit_log (event, details, logged_by, logged_on)
  VALUES (p_event, SUBSTR(p_details, 1, 400), USER, SYSTIMESTAMP);
  COMMIT;
END log_event;
/

CREATE OR REPLACE TRIGGER trg_atm_daily_limit
FOR INSERT ON atm_txn
COMPOUND TRIGGER
  TYPE t_keys IS TABLE OF DATE INDEX BY VARCHAR2(60);
  g_keys t_keys;

  AFTER EACH ROW IS
  BEGIN
    g_keys(:NEW.acct_id || '|' || TO_CHAR(:NEW.txn_date, 'YYYYMMDD'))
      := TRUNC(:NEW.txn_date);
  END AFTER EACH ROW;

  AFTER STATEMENT IS
    l_key   VARCHAR2(60) := g_keys.FIRST;
    l_acct  NUMBER;
    l_total NUMBER;
  BEGIN
    WHILE l_key IS NOT NULL LOOP
      l_acct := TO_NUMBER(SUBSTR(l_key, 1, INSTR(l_key, '|') - 1));
      SELECT NVL(SUM(amount), 0) INTO l_total
      FROM atm_txn
      WHERE acct_id = l_acct
        AND txn_date >= g_keys(l_key)
        AND txn_date <  g_keys(l_key) + 1;
      IF l_total > 50000 THEN
        RAISE_APPLICATION_ERROR(-20010,
          'Daily ATM limit exceeded for account ' || l_acct);
      END IF;
      l_key := g_keys.NEXT(l_key);
    END LOOP;
  END AFTER STATEMENT;
END trg_atm_daily_limit;
/

