DECLARE
  CURSOR c IS
    SELECT pay_id FROM payment_queue
    WHERE status = 'PENDING'
    ORDER BY created_ts
    FOR UPDATE SKIP LOCKED;
  l_id payment_queue.pay_id%TYPE;
BEGIN
  OPEN c;
  FETCH c INTO l_id;          -- locks one free row
  IF c%FOUND THEN
    UPDATE payment_queue SET status = 'PROCESSING' WHERE pay_id = l_id;
  END IF;
  CLOSE c;
  COMMIT;
END;
/

